// `mcp-connector deploy apply --target <t>` — actually deploys to the
// cloud, using the config previously generated by `deploy init --target <t>`.
//
// Today (2026-07) only `--target fly` is implemented. It shells out to the
// emitted fly-deploy.sh — the bash script is a proven, idempotent runner
// that already handles Fly's imperative CLI (create-if-missing checks for
// apps / postgres / secrets / volumes, then `fly deploy`). Wrapping it in
// a Node verb gives operators the same CLI surface (`mcp-connector deploy
// apply`) they'd expect for other targets when those land.
//
// Rationale for the shell-out vs. a native Node rewrite:
//   1. The bash script survived the live Fly deploy — no reason to rewrite
//      working code just to move it across languages.
//   2. Fly's CLI doesn't have a clean JSON-first mode for every operation
//      (some queries are text-only); the bash grep-based idempotency guards
//      are the pragmatic path. Node would need the same grep logic.
//   3. Keeping the bash script also serves operators who want to `cat` +
//      audit it before running — a common posture for security-conscious
//      customers deploying into production.
//
// Future targets (fargate / gke / aca / compose) will likely land as native
// Node implementations since their tools (aws / kubectl / az / docker
// compose) have JSON output modes and declarative apply semantics — no need
// for the imperative-fork-with-grep pattern that Fly's CLI forces.

import { parseArgs } from "node:util";
import { spawnSync } from "node:child_process";
import { existsSync } from "node:fs";
import { resolve } from "node:path";
import { createLogger } from "../logger.js";

const log = createLogger("deploy-apply");

const USAGE = `usage: mcp-connector deploy apply --target <t>

Actually deploys to the cloud using the config from a prior \`deploy init\`.

Targets (today):
  fly     Run the emitted fly-deploy.sh from the current directory. Idempotent —
          skips resources that already exist, creates ones that don't, then
          runs \`fly deploy\` in the foreground.

Not yet implemented: fargate, gke, aca, compose. For those, apply manually
with the cloud's native tool (aws / kubectl / az / docker compose).

Flags:
  --target <t>          required
  -h, --help            show this help`;

export async function runDeployApply(argv: string[]): Promise<number> {
  const { values } = parseArgs({
    args: argv,
    options: {
      target: { type: "string" },
      help: { type: "boolean", short: "h" },
    },
    allowPositionals: false,
  });

  if (values.help) {
    process.stdout.write(`${USAGE}\n`);
    return 0;
  }

  const target = values.target;
  if (!target) {
    process.stderr.write(`error: --target is required\n\n${USAGE}\n`);
    return 2;
  }

  switch (target) {
    case "fly":
      return applyFly();
    case "fargate":
    case "gke":
    case "aca":
    case "compose":
    case "fly-mock":
      process.stderr.write(
        `error: \`deploy apply --target ${target}\` is not yet implemented.\n\n` +
        `Generate the manifests with \`mcp-connector deploy init --target ${target}\`\n` +
        `then apply with the cloud's native tool (see readmeAppendix from init).\n`,
      );
      return 2;
    default:
      process.stderr.write(`error: unknown target "${target}"\n\n${USAGE}\n`);
      return 2;
  }
}

// Spawn the emitted fly-deploy.sh with stdio inherited so the operator sees
// build progress live. Return whatever exit code the bash script emits so
// CI wrappers can gate on success. Idempotency + error handling live in the
// script, not here — this wrapper is deliberately thin.
//
// `spawn` is injected so tests can supply a fake without vi.spyOn'ing the
// child_process module (which doesn't work under native ESM — vitest can't
// redefine module namespace properties). Default is Node's spawnSync.
export type SpawnFn = typeof spawnSync;

export function applyFly(
  cwd: string = process.cwd(),
  spawn: SpawnFn = spawnSync,
): number {
  const scriptPath = resolve(cwd, "fly-deploy.sh");

  if (!existsSync(scriptPath)) {
    log.error(
      { scriptPath },
      `fly-deploy.sh not found — run \`mcp-connector deploy init --target fly\` first to generate it`,
    );
    return 1;
  }

  const result = spawn("bash", [scriptPath], {
    cwd,
    stdio: "inherit",
  });

  if (result.error) {
    log.error({ err: result.error }, `failed to spawn bash for fly-deploy.sh`);
    return 1;
  }

  return result.status ?? 1;
}
